def el(cls,folder,inner,slot=None,data=''):
 style=(' style="grid-column:'+str(slot[0])+' / span '+str(slot[1])+';grid-row:'+str(slot[2])+' / span '+str(slot[3])+(';' +data if data else '')+'"') if slot else (' style="'+data+'"' if data else '')
 return f'<div class="{cls}" data-el="undertow-{folder}"{style}>{inner}</div>'
def name(s):return '<b class="name">'+s+'</b>'
def note(s):return '<p class="note">'+s+'</p>'
def parts(n,d='',fig='',kick='',mark=''):
 return '<div class="parts">'+('<p class="kick">'+kick+'</p>' if kick else '')+(f'<span class="mark">{mark}</span>' if mark else '')+('<p class="fig">'+fig+'</p>' if fig else '')+name(n)+(note(d) if d else '')+'</div>'
def card(n,d='',slot=None,cls='',fig='',kick='',mark=''):return el('card '+cls,'card',parts(n,d,fig,kick,mark),slot)
def head(n,lab,t,sec):return '<section class="slide"><div class="page"><div class="top"><span>'+sec+'</span><b>MIRI COMPANY</b></div><div class="rail">투자 유치를 위한 IR 덱 상세 템플릿<span>'+str(n-2).zfill(2)+'</span></div><header class="head center"><p class="kicker">'+lab+'</p><h1 class="title">'+t+'</h1></header><div class="body">'
def close():return '</div></div></section>'
def headline(t,d='',slot=None,cls='',kick=''):return el('headline '+cls,'headline',('<p class="kick">'+kick+'</p>' if kick else '')+'<h2>'+t+'</h2>'+(note(d) if d else ''),slot)
def prose(s,slot=None):return el('prose','prose','<p>'+s+'</p>',slot)
def call(s,slot=None):return el('callout','callout','<p>'+s+'</p>',slot)
def group(s,slot,cls=''):return '<div class="group '+cls+'" style="grid-column:'+str(slot[0])+' / span '+str(slot[1])+';grid-row:'+str(slot[2])+' / span '+str(slot[3])+'">'+s+'</div>'
def lista(xs,slot=None):return el('list divided','list',''.join('<div class="item">'+name(x)+'</div>' for x in xs),slot)
def icon(n):return '<span class="icon" data-icon="'+n+'"></span>'
